#ifndef LOG_H
#define LOG_H

#include <chrono>
#include <experimental/source_location>
#include <fstream>
#include <iostream>
#include <string>
#include <string_view>
#include <sstream>
#include <thread>
#include <mutex>
#include <deque>

namespace logging {

enum class Level {
    Debug,
    Info,
    Warn,
    Error,
    Fatal
};

enum class AppenderType {
    StdOut,
    File
};

class Event {
public:
    static Event Create(Level level, const std::source_location& location, std::thread::id thread_id);

    Event(const Event&) = delete;
    Event& operator=(const Event&) = delete;

    Level GetLevel() const { return level_; }
    std::string_view GetFileName() const { return file_name_; }
    int GetLineNumber() const { return line_num_; }
    std::thread::id GetThreadId() const { return thread_id_; }
    std::chrono::system_clock::time_point GetTime() const { return time_; }
    std::string_view GetMessage() const { return msg_; }

private:
    Level level_; 
    std::string_view file_name_; 
    int line_num_; 
    std::thread::id thread_id_; 
    std::chrono::system_clock::time_point time_; 
    std::string_view msg_; 

    std::ostringstream message_stream_; // Used to build the message.
};

class Formatter {
public:
    static Formatter Default();

    Formatter(const std::string& pattern);

    std::string Format(const Event& event) const;
    std::string_view Pattern() const { return pattern_; }

private:
    std::string pattern_; 
    //std::vector<Field*> fields_; // Fields to extract data from the event.
};

class Formatter::Field {
public:
    virtual ~Field() = default;
    virtual std::string Format(const Event& event) const = 0;
    virtual std::string_view Tag() const = 0;
};

class Appender {
public:
    Appender(Formatter formatter);
    virtual ~Appender() = default;

    virtual void Log(const Event& event) = 0;
    std::string ToYamlString() const; 
    Formatter GetFormatter() const { return formatter_; }
    void SetFormatter(Formatter formatter); 
private:
    Formatter formatter_;
};

class StdOutAppender : public Appender {
public:
    StdOutAppender(Formatter formatter) : Appender(formatter) {}
    void Log(const Event& event) override;
};

class FileAppender : public Appender {
public:
    FileAppender(Formatter formatter, const std::string& file_name);
    void Log(const Event& event) override;
private:
    std::string file_name_; 
    std::ofstream file_; 
};

class Logger {
public:
    Logger(const std::string& name, Level level = Level::Info, size_t capacity = 1024, bool async = false);
    ~Logger();

    void Log(Level level, const std::string_view& message);
    void AddAppender(Appender* appender);
    void RemoveAppender(Appender* appender);
    void ClearAppenders();
    Level GetLevel() const { return level_; }
    void SetLevel(Level level); 
    Formatter GetDefaultFormatter() const { return formatter_ };
    void SetDefaultFormatter(Formatter formatter); 
    std::string ToYamlString() const; 
private:
    void AsyncLogProc();

    std::string name_; 
    Level level_; 
    size_t capacity_; 
    bool async_; 
    std::deque<Event> event_deque_; 
    std::thread writer_thread_; 
    std::vector<Appender*> appenders_; 
    Formatter formatter_;
};

class EventWriter {
public:
    EventWriter(Logger& logger, Level level, const std::string_view& message);
    ~EventWriter();
private:
    Logger& logger_; 
    Level level_; 
    std::string_view message_; 
};

class Manager {
public:
    Manager(const std::string& name);
    ~Manager();

    Logger* FindLogger(const std::string& logger_name); 
    void RemoveLogger(const std::string& logger_name);
    std::string ToYamlString() const; 
private:
    std::string name_; 
    std::map<std::string, Logger> loggers_; 
};

}
#endif // LOG_H

#include "log.h"

namespace logging {

Event Event::Create(Level level, const std::source_location& location, std::thread::id thread_id) {
    return Event {level, location.file_name(), location.line(), thread_id, std::chrono::system_clock::now(), ""};
}

Formatter Formatter::Default() {
    return Formatter("%t %l: %m");
}

Formatter::Formatter(const std::string& pattern) : pattern_(pattern) {}

std::string Formatter::Format(const Event& event) const {
    std::stringstream ss;
    // Implement formatting logic here based on the pattern and event data.
    ss << "Formatted message for level: " << static_cast<int>(event.GetLevel()) << ", message: " << event.GetMessage();
    return ss.str();
}

Appender::Appender(Formatter formatter) : formatter_(formatter) {}

std::string Appender::ToYamlString() const {
    return "{\"type\": \"appender\", \"formatter\": \"" + formatter_.Pattern() + "\"}";
}

void Appender::SetFormatter(Formatter formatter) {
    formatter_ = formatter;
}

void StdOutAppender::Log(const Event& event) {
    std::cout << formatter_.Format(event) << std::endl;
}

FileAppender::FileAppender(Formatter formatter, const std::string& file_name) : Appender(formatter), file_name_(file_name) {
    file_.open(file_name_, std::ios::app);
    if (!file_.is_open()) {
        throw std::runtime_error("Failed to open file: " + file_name_);
    }
}

void FileAppender::Log(const Event& event) {
    file_ << formatter_.Format(event) << std::endl;
    file_.flush();
}

Logger::Logger(const std::string& name, Level level, size_t capacity, bool async) : 
    name_(name), level_(level), capacity_(capacity), async_(async), formatter_(Formatter::Default()) {
    if (async_) {
        writer_thread_ = std::thread(&Logger::AsyncLogProc, this);
    }
}

Logger::~Logger() {
    if (async_) {
        writer_thread_.join();
    }
    for (auto* appender : appenders_) {
        delete appender;
    }
}

void Logger::Log(Level level, const std::string_view& message) {
    Event event = Event::Create(level, std::source_location::current(), std::this_thread::get_id());
    //event.GetMessageStream() << message;
    //Event final_event = event;
    Log(event);
}

void Logger::Log(const Event& event) {
    if (level_ <= event.GetLevel()) {
        for (auto* appender : appenders_) {
            appender->Log(event);
        }
    }
}

void Logger::AddAppender(Appender* appender) {
    appenders_.push_back(appender);
}

void Logger::RemoveAppender(Appender* appender) {
    // Implement removal logic here.
}

void Logger::ClearAppenders() {
    appenders_.clear();
}

std::string Logger::ToYamlString() const {
    return "{\"type\": \"logger\", \"name\": \"" + name_ + "\", \"level\": \"" + static_cast<std::string>(static_cast<int>(level_)) + "\"}";
}

void Logger::AsyncLogProc() {
    while (true) {
        Event event;
        {
            std::lock_guard<std::mutex> lock(event_deque_mutex_);
            if (!event_deque_.empty()) {
                event = event_deque_.front();
                event_deque_.pop_front();
            }
        }
        Log(event);
    }
}

EventWriter::EventWriter(Logger& logger, Level level, const std::string_view& message) : 
    logger_(logger), level_(level), message_(message) {
    logger_.Log(level_, message_);
}

EventWriter::~EventWriter() {}

Manager::Manager(const std::string& name) : name_(name) {}

Manager::~Manager() {}

Logger* Manager::FindLogger(const std::string& logger_name) {
    auto it = loggers_.find(logger_name);
    if (it != loggers_.end()) {
        return &it->second;
    }
    return nullptr;
}

void Manager::RemoveLogger(const std::string& logger_name) {
    loggers_.erase(logger_name);
}

std::string Manager::ToYamlString() const {
    return "{\"type\": \"manager\", \"name\": \"" + name_ + "\"}";
}
}

